<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{{ $invoice->invoice_number }}</title><style>:root{--hm-gold:#f1b733;--hm-ink:#050816}*{box-sizing:border-box}body{font-family:Arial,sans-serif;max-width:850px;margin:40px auto;padding:0 20px;color:#14213d}.brand-document-header{display:flex;align-items:center;justify-content:space-between;gap:32px;border-bottom:3px solid var(--hm-gold);padding-bottom:20px}.brand-document-identity img{display:block;width:96px;height:auto;object-fit:contain}.brand-document-meta{text-align:right;line-height:1.6}.brand-image-fallback{display:inline-grid;place-items:center;width:72px;height:72px;border-radius:50%;background:var(--hm-gold);color:var(--hm-ink);font-weight:800}table{width:100%;border-collapse:collapse;margin-top:30px}th,td{padding:12px;border-bottom:1px solid #ddd;text-align:left}.total{text-align:right;font-size:1.3rem;margin-top:24px}@media(max-width:520px){body{margin:20px auto}.brand-document-header{align-items:flex-start;flex-direction:column}.brand-document-meta{text-align:left}}@media print{body{margin:0;max-width:none}}</style></head><body><x-brand.document-header><strong>{{ $invoice->invoice_number }}</strong><br>Direct advertising invoice<br>Issued {{ $invoice->issued_on }}<br>Due {{ $invoice->due_on }}</x-brand.document-header><h2>Bill to</h2><p>{{ $invoice->billingProfile?->legal_name ?? $invoice->advertiser->legal_name }}<br>{{ $invoice->billingProfile?->billing_email ?? $invoice->advertiser->billing_email }}</p><table><thead><tr><th>Description</th><th>Pricing</th><th>Amount</th></tr></thead><tbody>@foreach($invoice->line_items as $item)<tr><td>{{ $item['description'] }}</td><td>{{ $item['pricing_model'] }}</td><td>{{ $invoice->currency }} {{ number_format($item['amount_minor']/100,2) }}</td></tr>@endforeach</tbody></table><div class="total">Subtotal: {{ $invoice->currency }} {{ number_format($invoice->subtotal_minor/100,2) }}<